const translationDictionaries = {
  bn: bnTranslations,
  or: orTranslations,
  te: teTranslations,
};

function polishBengaliText(text) {
  return text
    .replace(/\bAI\b/g, "এআই")
    .replace(/\bERP\b/g, "ইআরপি")
    .replace(/\bIT\b/g, "আইটি")
    .replace(/\bFAQ\b/g, "প্রশ্নোত্তর")
    .replace(/\bLayerX\b/g, "লেয়ারএক্স")
    .replace(/\bThe Brain\b/g, "দ্য ব্রেইন")
    .replace(/\bPro\b/g, "প্রো");
}

function polishTranslatedText(text, language) {
  if (language === "bn") return polishBengaliText(text);
  return text;
}

function translateTextNodes(root, language) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      if (node.parentElement?.closest("script, style, input, textarea, select")) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => {
    node.__originalText ||= node.nodeValue;
    const source = node.__originalText.trim();
    const translated = translationDictionaries[language]?.[source];
    if (language !== "en" && translated) {
      node.nodeValue = node.__originalText.replace(source, polishTranslatedText(translated, language));
    } else {
      node.nodeValue = node.__originalText;
    }
  });
}

